/// A substitution protocol: what to dispense when a drug cannot be,
/// written as a decision tree the team walks through.
#[derive(Clone, Debug)]
pub struct Protocol {
    pub id: i64,
    pub title: String,
    /// The drug or class it is about, free text.
    pub subject: String,
}

/// What a node of a protocol does.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NodeKind {
    /// A yes/no question: "DFG inférieur à 30 ?", "Xarelto disponible ?"
    Question,
    /// What to do: dispense, call the prescriber, list a class.
    Action,
}

impl NodeKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Question => "QUESTION",
            Self::Action => "ACTION",
        }
    }
    pub fn parse(s: &str) -> Self {
        if s == "QUESTION" {
            Self::Question
        } else {
            Self::Action
        }
    }
}

/// Which branch of its parent a node hangs from.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Branch {
    Root,
    Yes,
    No,
}

impl Branch {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Root => "ROOT",
            Self::Yes => "YES",
            Self::No => "NO",
        }
    }
    pub fn parse(s: &str) -> Self {
        match s {
            "YES" => Self::Yes,
            "NO" => Self::No,
            _ => Self::Root,
        }
    }
}

/// One step of a protocol.
#[derive(Clone, Debug)]
pub struct ProtocolNode {
    pub id: i64,
    pub parent_id: Option<i64>,
    pub branch: Branch,
    pub kind: NodeKind,
    pub text: String,
    pub position: i64,
}

