    #[test]
    fn starter_drugs_seed_once_and_never_resurrect() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-sdrug-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("starter.db");
        let _ = std::fs::remove_file(&path);

        let db = Db::open(&path, "secret").unwrap();
        // No duplicate brand names in the starter list (the per-name
        // NOT EXISTS guard would silently drop them).
        let mut names: Vec<&str> = STARTER_DRUGS.iter().map(|(n, _, _, _)| *n).collect();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), STARTER_DRUGS.len());
        // Nor two spellings of the same brand: "Kaléorid" and
        // "Kaleorid" were both in the list, giving one product two
        // cards and only one of them a monograph.
        let mut folded: Vec<String> = STARTER_DRUGS
            .iter()
            .map(|(n, _, _, _)| crate::fuzzy::sort_key(n).replace([' ', '-'], ""))
            .collect();
        folded.sort();
        let total = folded.len();
        folded.dedup();
        assert_eq!(
            folded.len(),
            total,
            "deux orthographes d'une même spécialité dans la liste de départ"
        );

        let n = db.seed_drugs_if_empty().unwrap();
        assert_eq!(n, STARTER_DRUGS.len());
        let eliquis = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| d.name == "Eliquis")
            .unwrap();
        assert_eq!(eliquis.dci, "apixaban");
        assert_eq!(eliquis.class, "AOD");
        assert_eq!(eliquis.antidote, "Andexanet alfa");
        // Eliquis is one of the detailed cards; a drug outside that
        // list ships identity only, its clinical fields left to the team.
        assert!(!eliquis.dosage.is_empty());
        // Any card outside the detailed list ships identity only. The
        // list grows over time, so the example is picked, not named.
        let detailed: std::collections::HashSet<&str> =
            STARTER_DETAILS.iter().map(|d| d.name).collect();
        // Every card carries a monograph today; should one be added
        // without, it must ship identity only.
        if let Some(plain) = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| !detailed.contains(d.name.as_str()))
        {
            assert!(
                plain.dosage.is_empty() && plain.ddi.is_empty() && plain.iup.is_empty(),
                "la fiche « {} » porte du texte clinique sans monographie",
                plain.name
            );
        }

        // Second run: no-op. After a deliberate deletion: still no-op.
        assert_eq!(db.seed_drugs_if_empty().unwrap(), 0);
        assert!(db.delete_drug(eliquis.id, "Eliquis").unwrap());
        assert_eq!(db.seed_drugs_if_empty().unwrap(), 0);
        assert!(db.drugs().unwrap().iter().all(|d| d.name != "Eliquis"));

        let _ = std::fs::remove_file(&path);
    }

